window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"ko-MqppeG_E","speaker":"Jessica Rose Epel Alupo","role":"Vice President","country":"Uganda","region":"Africa","url":"https://www.youtube.com/watch?v=ko-MqppeG_E","date":"20260924","title":"🇺🇬 Uganda - Vice President Addresses United Nations General Assembly 81st Session | #UNGA","seconds":666,"words":1054,"counts":{"claims":15,"promises":0,"attacks":0},"topics":[{"topic":"UN governance","share":0.243,"seconds":162},{"topic":"Uganda health","share":0.1958,"seconds":130},{"topic":"UN Security Council","share":0.1318,"seconds":88},{"topic":"Uganda economy","share":0.1018,"seconds":68},{"topic":"Sustainable development","share":0.1011,"seconds":67},{"topic":"Global taxation","share":0.0991,"seconds":66},{"topic":"Non-Aligned Movement","share":0.0903,"seconds":60},{"topic":"UN operations","share":0.0371,"seconds":25}],"timeline":[[0,61,null],[63,124,null],[125,206,"UN governance"],[207,295,"UN Security Council"],[297,365,"Sustainable development"],[366,432,"Global taxation"],[435,503,"Uganda economy"],[504,574,"Uganda health"],[576,636,"Uganda health"],[638,698,"Non-Aligned Movement"],[700,780,"UN governance"],[782,807,"UN operations"]],"stances":{"UN governance":"The speaker asserts that the UN Charter's founding principles must be reflected upon and recommitted to in order to avert warfare and address shared challenges.","UN Security Council":"Uganda calls for comprehensive reforms to the UN Security Council to make it more equitable and demands Africa's representation in both permanent and non-permanent categories.","Sustainable development":"The speaker argues that reform processes must not undermine the 2030 agenda and highlights that progress is hindered by limited resources and debt servicing.","Global taxation":"Uganda supports ongoing negotiations on the UN Framework Convention on international tax cooperation and urges constructive negotiation by all member states.","Uganda economy":"The speaker outlines Uganda's national development strategy aimed at achieving double-digit growth and a tenfold increase in GDP by 2040 through specific pillars like tourism and technology.","Uganda health":"The speaker states that investing in a healthy population is a core strategic priority and outlines specific investments under NDP 4 to improve healthcare access and service delivery.","Non-Aligned Movement":"Uganda is upholding NAM principles and advancing the 1986 covenant on the right to development while preparing to host a ministerial meeting in Kampala.","UN operations":"The speaker asserts that renewed international cooperation will enable the UN to fulfill its founding promises for humanity."},"claims":[{"t":126,"quote":"80 years ago, the United Nations was established in the aftermath of the Second World War to foster international cooperation and prevent future armed conflicts.","topic":"UN governance","kind":"fact"},{"t":251,"quote":"We call for a comprehensive reform to render the Council more equitable, transparent, democratic, and In this regard, we demand Africa's rightful representation in both the permanent and non-permanent categories to correct historical imbalances in line with the common African position articulated in the Ezulwini Consensus and the Sirte","topic":"UN Security Council","kind":"fact"},{"t":316,"quote":"when we adopted the 2030 agenda for the 17 SDGs in 2015, we committed to leaving no one behind.","topic":"Sustainable development","kind":"fact"},{"t":329,"quote":"progress remains elusive with only 36% of the 139 targets currently on","topic":"Sustainable development","kind":"number"},{"t":366,"quote":"This challenge requires urgent reform of international financial architecture to afford developing nations a stronger voice in decision-making alongside the full implementation of the Sevilla commitment of the pact for the Furthermore, equitable taxation is essential for mobilizing domestic An inclusive international tax system is critical for strengthening global cooperation, curbing illicit financial flows and addressing profit shifting by multinational corporations.","topic":"Global taxation","kind":"fact"},{"t":466,"quote":"Our goal is to drive double-digit growth over the 5-year period and ultimately grow our economy tenfold to a GDP of 500 billion US dollars by 2040","topic":"Uganda economy","kind":"number"},{"t":551,"quote":"Under NDP 4, we are expanding health investments to ensure accessible, affordable, and equitable health care across the country.","topic":"Uganda health","kind":"fact"},{"t":562,"quote":"This includes modernizing health centers, upgrading regional referral hospitals, and integrating digital health solutions to improve service delivery and accountability.","topic":"Uganda health","kind":"fact"},{"t":592,"quote":"keeping Uganda on track to achieve the UNAIDS 95-95-95 targets and contribute to end the ending AIDS as a public health threat by 20 30","topic":"Uganda health","kind":"fact"},{"t":607,"quote":"Having successfully contained outbreaks such as the Bundibugyo Ebola virus Uganda has built a resilient public health framework","topic":"Uganda health","kind":"fact"},{"t":649,"quote":"We remain dedicated to advancing the international covenant on the right to development aiming to transform the 1986 into a binding operational instrument that tackles structural global","topic":"Non-Aligned Movement","kind":"fact"},{"t":668,"quote":"We look forward to hosting the ministers of NAM member states and observers at the ministerial meeting of the NAM Coordinating Bureau in Kampala from December 2nd to 4th, 2026.","topic":"Non-Aligned Movement","kind":"fact"},{"t":713,"quote":"As the inaugural Special Representative for Children and Armed Conflict he placed the protection of war-affected children firmly on the on the Security Council agenda and established the monitoring and reporting mechanism under resolution 1612 in 2005.","topic":"UN governance","kind":"fact"},{"t":756,"quote":"for eight decades, the United Nations has stood as a central pillar of international peace, human rights, and While acknowledging its vital achievements and convening power","topic":"UN governance","kind":"fact"},{"t":782,"quote":"Through renewed international cooperation, the UN can truly deliver on its founding promises for all humanity.","topic":"UN operations","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":null,"text":"The assembly will hear an address by her Jessica Rose Epel Alupo, Vice President of the Republic of I request protocol to escort her Excellency and invite her to address the &gt;&gt; The President of the UN General Excellencies, the heads of state and the Secretary General of the United Nations, distinguished delegates, ladies and gentlemen, I wish to bring you warm greetings from His Excellency General Yoweri Kaguta President of the Republic of Uganda, on whose behalf I am delivering this statement. And the statement reads as follows."},{"t":63,"topic":null,"text":"I wish to express my gratitude for the invitation extended to me to address this 81st session of the United Nations General Assembly. I have been unable to attend in person and delegated her Excellency Major Retired Jessica Alupo Rose Epel, Vice President of the Republic of Uganda to represent me. I congratulate His Excellency Dr. Csaba Kőrösi Rahman on your election as President of the 81st session of the UN General Assembly and assure you of Uganda's full support. I also thank His Excellency Her Excellency Miss Anna Lena Baerbock for her stewardship of the 80th session and wish to thank the Secretary General, His Excellency Antonio Guterres for his unwavering commitment to the United Mr."},{"t":125,"topic":"UN governance","text":"President, 80 years ago, the United Nations was established in the aftermath of the Second World War to foster international cooperation and prevent future armed conflicts. As we convene here today, we must confront the reality of living in very uncertain times shadowed by the persistent threat of global conflict. It is imperative that we work together to avert warfare. We must reflect on the founding principles of the UN Charter and recommit ourselves to saving succeeding generations from the scourge of war, reaffirming faith in fundamental human rights and the dignity of human person, ensuring equal rights for all large nations and small, establishing conditions for justice and respect for international law, and promoting social progress alongside better standards of Uganda family believes that multilateralism and international remain the most vital mechanisms for addressing our shared challenges."},{"t":207,"topic":"UN Security Council","text":"Accordingly, we remain and reaffirm our commitment to the principles of the UN Charter as the cornerstone of global supporting the interconnected pillars of peace and security, human rights, humanitarian affairs, and sustainable development. We believe the United Nations must remain agile and adaptive to evolving global realities. Uganda is committed to working with the entire membership to build consensus on necessary systemic reforms, particularly within the UN Security Council. We call for a comprehensive reform to render the Council more equitable, transparent, democratic, and In this regard, we demand Africa's rightful representation in both the permanent and non-permanent categories to correct historical imbalances in line with the common African position articulated in the Ezulwini Consensus and the Sirte Regarding the ongoing UN aid initiative, Uganda commends efforts to streamline the UN system to make it cost-effective, efficient, and well-coordinated."},{"t":297,"topic":"Sustainable development","text":"However, these reform processes must not dilute agreed UN mandates, commitments, and programs, nor should they impede the implementation of the 2030 agenda. Mr. President, when we adopted the 2030 agenda for the 17 SDGs in 2015, we committed to leaving no one behind. Yet, progress remains elusive with only 36% of the 139 targets currently on Numerous obstacles hinder our efforts to accelerate progress, key among being limited physical space. many developing countries lack sufficient financial resources to fund their development needs with a disproportionate share of revenues directed towards debt servicing rather than critical public infrastructure and social services."},{"t":366,"topic":"Global taxation","text":"This challenge requires urgent reform of international financial architecture to afford developing nations a stronger voice in decision-making alongside the full implementation of the Sevilla commitment of the pact for the Furthermore, equitable taxation is essential for mobilizing domestic An inclusive international tax system is critical for strengthening global cooperation, curbing illicit financial flows and addressing profit shifting by multinational corporations. Mr. President, Uganda fully supports the ongoing intergovernmental negotiation on the United Nations Framework Convention on international tax cooperation and its protocols on cross-border services and tax dispute resolution, and we urge all member states to negotiate constructively."},{"t":435,"topic":"Uganda economy","text":"Uganda has commended the implementation of its fourth national development plan as part of our national strategy to accelerate economic transformation and achieve sustainable development. This strategy is anchored on four high-impact growth pillars, including tourism development, mineral exploitation, and science, technology, and innovation. Our goal is to drive double-digit growth over the 5-year period and ultimately grow our economy tenfold to a GDP of 500 billion US dollars by 2040, creating jobs and enhancing the quality of life of all Ugandans. Mr. President, distinguished delegates, the peaceful resolution of conflicts through diplomacy is indispensable for sustainable peace, security, and economic growth."},{"t":504,"topic":"Uganda health","text":"Most conflicts arise from unresolved local and regional grievances and demand comprehensive politically led and locally owned solutions rather than purely military responses. Uganda remains a consistent contributor to regional stability, particularly in the Horn of Africa and the Great Lakes region, and our security approach is rooted in a Pan-African framework that seeks peace through collective alliances and regional Mr. President, investing in a healthy population remains a core strategic priority for Under NDP 4, we are expanding health investments to ensure accessible, affordable, and equitable health care across the country. This includes modernizing health centers, upgrading regional referral hospitals, and integrating digital health solutions to improve service delivery and accountability."},{"t":576,"topic":"Uganda health","text":"We are actively addressing the dual burden of communicable and non-communicable diseases and our responses to HIV AIDS combine strong political leadership with sustained community involvement keeping Uganda on track to achieve the UNAIDS 95-95-95 targets and contribute to end the ending AIDS as a public health threat by 20 30. Having successfully contained outbreaks such as the Bundibugyo Ebola virus Uganda has built a resilient public health framework. We call upon development partners and multilateral institutions to bridge financing gaps, enhance pandemic preparedness, and ensure equitable access to diagnostic tools, medicines, and vaccines worldwide."},{"t":638,"topic":"Non-Aligned Movement","text":"As the chair of NAM, Uganda continues to uphold the principles of unity, peace, and solidarity among developing nations. We remain dedicated to advancing the international covenant on the right to development aiming to transform the 1986 into a binding operational instrument that tackles structural global We look forward to hosting the ministers of NAM member states and observers at the ministerial meeting of the NAM Coordinating Bureau in Kampala from December 2nd to 4th, 2026. Mr. President as [snorts] the selection process for next for the next UN Secretary General progresses Uganda has presented a candidate in the name of Ambassador Olara Otunnu."},{"t":700,"topic":"UN governance","text":"Ambassador Olara Otunnu brings over four decades of distinguished service across the UN system, international diplomacy, and public administration. As the inaugural Special Representative for Children and Armed Conflict he placed the protection of war-affected children firmly on the on the Security Council agenda and established the monitoring and reporting mechanism under resolution 1612 in 2005. His extensive experience, statesmanship, and proven capacity for make him exceptionally qualified to lead the Secretariat at this critical time. As I conclude, Mr. President, for eight decades, the United Nations has stood as a central pillar of international peace, human rights, and While acknowledging its vital achievements and convening power, we must continue to reform the organization to ensure it becomes more transparent, efficient, and representative."},{"t":782,"topic":"UN operations","text":"Through renewed international cooperation, the UN can truly deliver on its founding promises for all humanity. I thank you for your kind attention. &gt;&gt; On behalf of the Assembly, I wish to thank the Vice President of the Republic of Uganda."}],"compare":[{"topic":"UN & its reform","share":0.4118,"mean":0.2037,"rank":18,"others":170},{"topic":"Sustainable Development","share":0.1011,"mean":0.012,"rank":7,"others":28},{"topic":"Global Economy","share":0.0991,"mean":0.0141,"rank":9,"others":31},{"topic":"International Law & Order","share":0.0903,"mean":0.0602,"rank":50,"others":102}]};
